    if Wait ~= nil and Kind(Wait) ~= "function" then Raise(0, 0); end;
    local function Cancel()
        Dead = true;
        Chunks = {};
        ContainerKey, ModuleKey, Remote, Salt = nil, nil, nil, nil;
    end;
    local Resolve;
    Resolve = function(PathA, PathB)
        if Dead then Raise(0, 0); end;
        local Entry = Catalog[Text(PathA) .. ":" .. Text(PathB)];
        if not Entry then
            if Public then return Public(PathA, PathB); end;
            Dead = true;
            Raise(0, 0);
        end;
        local Id, Base = Entry[1], Entry[2];
        if not Chunks[Id] then
            local Deadline = Clock() + 30;
            while Fetching[Id] do
                if Fetching[Id] == Running() or not Wait or Clock() > Deadline then Cancel(); Raise(0, 0); end;
                local Ok = ProtectedCall(Wait);
                if not Ok or Dead then Cancel(); Raise(0, 0); end;
            end;
            if Dead then Raise(0, 0); end;
            if Chunks[Id] then return Resolve(PathA, PathB); end;
            Fetching[Id] = Running();
            local Ok, Required = ProtectedCall(function()
                local Wrapped = Fetch(Id);
                if Dead then Raise(0, 0); end;
