            end);
            Fetching[Id] = nil;
            if not Ok or Dead then Cancel(); Raise(0, 0); end;
            Chunks[Id] = Required;
        end;
        local Ok, Value = ProtectedCall(Chunks[Id], PathA, PathB);
        if not Ok or Dead then Cancel(); Raise(0, 0); end;
        return Value;
    end;
    return Resolve, Cancel;
end;

